  sousStats: [["PV",503,375,300,249,198,150],["PV %","11 %","8 %","6 %","5 %","4 %","3 %"],["ATQ",27,20,16,13,11,8],["ATQ %","11 %","8 %","6 %","5 %","4 %","3 %"],["DÉF",27,20,16,13,11,8],["DÉF %","11 %","8 %","6 %","5 %","4 %","3 %"],["VIT",8,6,5,4,3,2],["Taux Crit %","8 %","6 %","5 %","4 %","3 %","2 %"],["Dég. Crit %","9 %","7 %","6 %","5 %","4 %","3 %"],["RÉS %","11 %","8 %","6 %","5 %","4 %","3 %"],["PRÉ %","11 %","8 %","6 %","5 %","4 %","3 %"]],
